  INSERT INTO questions (prompt, description, type, country_code,
    targeting_type, nsfw, is_hidden, is_private, author_id, is_seeded)
  VALUES ('What kind of texter are you?', NULL, 'multiple_choice', 'US', 'globe', false, false, false, NULL, true)
  RETURNING id
)
INSERT INTO question_options (question_id, option_text, sort_order)
SELECT q.id, o.option_text, o.sort_order
FROM q, (VALUES ('Instant replies', 0), ('A few times a day', 1), ('Days later', 2), ('Call me instead', 3)) AS o(option_text, sort_order);

